/* CubalC lang — lang_ops_flow_ifbag.c
 * FLOW IF residual: IFHASLINE/IFINBAG bag membership (A3 peel).
 * Mesh vote A3_carve_lang_ops_flow · zero bloat · cube is SoT.
 */
#include "lang/cubalc_lang_ops_flow_ifbag.h"
